// Filter out contacts who have already been messaged.
// Activity sheet is the single source of truth for dedup state.
const activity = $('Read Activity').all().map(i => i.json);
const alreadySent = new Set(
  activity
    .map(a => a.contact_email_or_url)
    .filter(Boolean)
    .map(String)
);

const items = $input.all();
const kept = items.filter(item => {
  const id = item.json.email || item.json.linkedin_url;
  if (!id) return false; // no usable channel identifier
  return !alreadySent.has(String(id));
});

return kept.map(i => ({ json: i.json }));

// 6 templates: 2 channels × 3 segments.
// Versioned inline so the methodology is visible in the workflow JSON,
// not hidden in an external prompt store.
const templates = {
  email_hiring: {
    subject: '{{first_name}}, SAP-Wachstum bei {{company}} & Hauptspeicher-Engpässe',
    body: `{{opener}}

Eine kurze Frage: bei {{company}} laufen aktuell mehrere SAP-Rollen offen. Wenn das Team in den nächsten 6–12 Monaten wächst, wird der Hauptspeicher meist erst zum Bottleneck, wenn das Projekt schon mitten in der Migration ist.

KGS Software macht genau das archivierungsseitig planbar — als Service, ohne dass Ihr Team es selbst aufbauen muss. Wir arbeiten mit Unternehmen wie {{customer_example}} zusammen.

Macht 20 Minuten nächste Woche Sinn, um zu zeigen, wie der Übergang typischerweise aussieht?

Beste Grüße,
{{sender_name}}`
  },
  email_regulated: {
    subject: '{{first_name}}, GoBD-konforme SAP-Archivierung bei {{company}}',
    body: `{{opener}}

In regulierten Branchen ist die Aufbewahrungspflicht inzwischen weniger das Problem als die Audit-Festigkeit. 10 Jahre GoBD-konform vorhalten, aber gleichzeitig die SAP-Performance nicht aushöhlen — das ist die eigentliche Spannung.

KGS Software löst das als Service: revisionssicher, GoBD-zertifiziert, SAP-zertifizierter Archivierungs-Stack. Kein eigenes Storage-Setup nötig.

20 Minuten nächste Woche — würde Ihnen zeigen, wie Kunden in Ihrer Branche das umgesetzt haben?

Beste Grüße,
{{sender_name}}`
  },
  email_mid_cap: {
    subject: '{{first_name}}, SAP-Storage-Kosten bei {{company}} reduzieren',
    body: `{{opener}}

Bei mittelständischen SAP-Installationen sehen wir typischerweise 60–70% der DB-Größe in selten genutzten Daten — alte Belege, abgeschlossene Vorgänge, archivpflichtige Dokumente. Diese Daten in der Live-DB zu halten kostet sowohl Lizenz als auch Performance.

KGS Software archiviert das als Service — auslagern, ohne neue Infrastruktur, ohne IT-Roadmap zu blockieren.

20 Minuten Demo nächste Woche? Ich kann konkret durchspielen, was das bei einer Installation Ihrer Größe spart.

Beste Grüße,
{{sender_name}}`
  },
  linkedin_hiring: {
    subject: '',
    body: `Hallo {{first_name}},

{{opener}}

{{company}} sucht aktuell mehrere SAP-Rollen — schöne Wachstumsphase. Eine Frage, die in der Phase oft unterschätzt wird: was passiert mit dem Hauptspeicher, wenn die Datenmenge mitskaliert?

Wir arbeiten mit Unternehmen wie {{customer_example}} an SAP-Archivierung als Service. Falls relevant, gerne 15 Minuten zum Austausch?

Beste Grüße`
  },
  linkedin_regulated: {
    subject: '',
    body: `Hallo {{first_name}},

{{opener}}

In Ihrer Branche kennen Sie das Thema GoBD-konforme Archivierung sicher gut. Wir machen das bei KGS Software als Service — SAP-zertifiziert, revisionssicher. Falls Ihr Team das Thema gerade priorisiert, gerne kurz zum Austausch?

Beste Grüße`
  },
  linkedin_mid_cap: {
    subject: '',
    body: `Hallo {{first_name}},

{{opener}}

Bei mittelständischen SAP-Setups laufen oft 60–70% selten genutzte Daten in der Live-DB mit. Wir archivieren das bei KGS Software als Service — ohne neue Infra. Interessant für {{company}}?

Beste Grüße`
  }
};

return $input.all().map(item => {
  const j = item.json;
  const segmentKey = (j.segment || 'mid_cap').replace('-', '_');
  const key = `${j.channel}_${segmentKey}`;
  const tpl = templates[key] || templates.email_mid_cap;
  return {
    json: {
      ...j,
      template_key: key,
      template_subject: tpl.subject,
      template_body: tpl.body
    }
  };
});

