// Merge LLM opener + template + merge tags into final subject/body.
const SENDER_NAME = 'Alberto Greene';
const CUSTOMER_EXAMPLE = 'einem führenden deutschen DAX-Konzern';

return $input.all().map(item => {
  const j = item.json;
  const opener = (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '';
  const prev = $('Pick Template (channel × segment)').first().json;

  // The HTTP node response shape replaces $json with the API response,
  // so merge fields come from the upstream Pick Template node.
  const ctx = {
    first_name: prev.first_name || '',
    company: prev.company || '',
    title: prev.title || 'Ihr Team',
    customer_example: CUSTOMER_EXAMPLE,
    sender_name: SENDER_NAME,
    opener: opener.trim()
  };

  const fill = (str) => Object.entries(ctx).reduce(
    (acc, [k, v]) => acc.split(`{{${k}}}`).join(v),
    str
  );

  return {
    json: {
      ...prev,
      opener: ctx.opener,
      final_subject: fill(prev.template_subject),
      final_message: fill(prev.template_body)
    }
  };
});
